from fastapi import FastAPI
from pydantic import BaseModel, Field
from typing import Optional

app = FastAPI(
    title='Payment API',
    description='Process payments and manage subscriptions',
    version='2.1.0',
    contact={'name': 'API Support', 'email': 'api@example.com'},
    openapi_tags=[
        {'name': 'users', 'description': 'User management operations'},
        {'name': 'payments', 'description': 'Payment processing'},
    ]
)

class UserCreate(BaseModel):
    """New user registration data."""
    username: str = Field(
        min_length=3,
        max_length=50,
        description='Unique username. 3-50 chars, alphanumeric and underscores only.',
        examples=['john_doe', 'alice123']
    )
    email: str = Field(description='User email address. Used for notifications and login.')

    model_config = {
        'json_schema_extra': {
            'examples': [
                {'username': 'john_doe', 'email': 'john@example.com'}
            ]
        }
    }

@app.post(
    '/users/',
    response_model=UserResponse,
    status_code=201,
    tags=['users'],
    summary='Create a new user account',
    description='''Create a new user account. Email must be unique. Username must be 3-50 chars.

    **Note:** Triggers a verification email to the provided address.
    ''',
    response_description='The created user object with server-assigned id and timestamps',
    responses={
        409: {'description': 'Username or email already exists'},
        422: {'description': 'Validation error — check field constraints'},
    }
)
